INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63905692', 63905692, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL KESEHATAN LANJUTAN', 'Procurement of Laboratory Equipment', 'Barang', 'Tender', 'DKI Jakarta, Jakarta Selatan (Kota)', 158584683130, 'February 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 0, 0, '1 Paket', 'Pengadaan Peralatan Laboratorium: Lot 1 : Thromboelastogram (TEG) (10 unit) Lot 2 : Laboratory Major Analyzer Equipment (Spectrometers, Mass, Laboratory) (4 unit) Lot 3 : Analyzers, Laboratory, Molecular Assay, Infectious Microorganism (12 unit) Lot 4 : Portable Blood Gas Analyzer (NICU) (389 unit) Lot 5 : Point-of-Care Bilirubinometer (43 unit)', 'Lot 1 : Thromboelastogram (TEG) (10 unit) : alat yang digunakan untuk menguji efisiensi pembekuan darah. Alat ini mengevaluasi sifat viskoelastik darah utuh, menawarkan penilaian rinci tentang fungsi hemostatik. Lot 2 : Laboratory Major Analyzer Equipment (Spectrometers, Mass, Laboratory) (4 unit) : Penganalisis laboratorium yang dirancang untuk identifikasi cepat mikroorganisme (bakteri, ragi, jamur, dan mikobakteri) menggunakan spektrometri massa ionisasi desorpsi laser berbantuan matriks waktu terbang (MALDI-TOF) Lot 3 : Analyzers, Laboratory, Molecular Assay, Infectious Microorganism (12 unit) : Alat analisis laboratorium diagnostik molekuler dirancang untuk menggunakan teknik diagnostik asam nukleat untuk mengidentifikasi dan/atau mengukur molekul spesifik yang dimiliki atau terkait dengan mikroorganisme (misalnya, bakteri, virus, jamur) yang menginfeksi manusia Lot 4 : Portable Blood Gas Analyzer (NICU) (389 unit) : alat digunakan untuk pengukuran langsung pH, tekanan parsial karbon dioksida (pCO₂), dan tekanan parsial oksigen (pO₂) dalam spesimen darah utuh Lot 5 : Point-of-Care Bilirubinometer (43 unit) : Instrumen portabel yang dirancang untuk penentuan konsentrasi bilirubin secara cepat dan akurat dalam sampel darah atau serum neonatus', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1185148);
