INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63884596', 63884596, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Direktorat Jenderal Tata Ruang', 'Perencanaan dan Pembinaan Lisensi Perencana Tata Ruang', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 303712000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '1', 'Penyelenggaraan penataan ruang merupakan kegiatan yang meliputi pengaturan, pembinaan, pelaksanaan, dan pengawasan penataan ruang. Sedangkan penataan ruang itu sendiri adalah suatu sistem perencanaan tata ruang, pemanfaatan ruang, dan pengendalian pemanfaatan ruang. Dalam penyelenggaraan penataan ruang diperlukan sumber daya manusia yang akan menjadi pelaksana dan dapat berprofesi sebagai perencana tata ruang. Tenaga profesional perencana tata ruang diharapkan dapat menjadi tenaga yang kompeten dalam perencanaan tata ruang. Kompetensi ini nantinya perlu dibuktikan secara tertulis ke dalam lisensi tenaga profesional perencana tata ruang yang akan diterbitkan oleh Menteri. Dengan adanya kompetensi ini nantinya akan menjadi dokumen dasar bagi tenaga profesional perencana tata ruang untuk dapat praktik keprofesian di seluruh wilayah Negara Indonesia. Menteri adalah menteri yang menyelenggarakan urusan pemerintahan di bidang pertanahan dan suburusan tata ruang yang merupakan lingkup urusan pemerintahan di bidang pekerjaan umum. Pada tahun 2026, Direktorat Perencanaan Tata Ruang Nasional akan melaksanakan kembali kegiatan Fasilitasi Perencanaan dan Pembinaan Lisensi Perencana Tata Ruang.', 'Keluaran Keluaran kegiatan ini yaitu berupa Dokumen Fasilitasi Perencanaan dan Pembinaan Perencana Tata Ruang. Pelaporan Laporan kegiatan ini terdiri atas: Laporan Pendahuluan Fasilitasi Perencanaan dan Pembinaan Perencana Tata Ruang yang diserahkan 1 (satu) bulan setelah pelaksanaan kegiatan dimulai; Laporan Akhir Fasilitasi Perencanaan dan Pembinaan Perencana Tata Ruang yang diserahkan pada bulan terakhir pelaksanaan kegiatan; dan Laporan Bulanan konsultan individu Kegiatan Fasilitasi Perencanaan dan Pembinaan Perencana Tata Ruang yang diserahkan setiap bulan selama pelaksanaan kegiatan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1186757);
